INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('10000000-0000-4000-8000-000000001020','3','choice','{"type":"choice","schemaVersion":1,"id":"10000000-0000-4000-8000-000000001020","revision":3,"targetId":"10000000-0000-4000-8000-000000000010","prompt":"Ich bespreche die Ergebnisse mit ___ Arzt. (der Arzt)","instruction":{"en":"Choose only the definite singular article that fits the noun after “mit”.","de":"Wähle nur den bestimmten Artikel im Singular, der nach „mit“ zum Nomen passt."},"hint":{"en":"mit always takes the dative. Match the article to the noun’s gender.","de":"„mit“ verlangt immer den Dativ. Passe den Artikel an das Genus des Nomens an."},"options":[{"id":"der","text":"der"},{"id":"die","text":"die"},{"id":"das","text":"das"},{"id":"den","text":"den"},{"id":"dem","text":"dem"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"dem"}],"explanation":{"en":"“mit” requires the dative. „der Arzt“ is masculine; in the dative singular the definite article is dem.","de":"„mit“ verlangt den Dativ. „der Arzt“ ist maskulin; im Dativ Singular lautet der bestimmte Artikel „dem“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich bespreche die Ergebnisse mit ","emphasis":false},{"text":"dem","emphasis":true},{"text":" Arzt.","emphasis":false}]}}','de-nfc-trim-v1','Original agent-authored examples for German Master 2.0; no imported dataset.','pending');
