INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001016','5','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001016","revision":5,"targetId":"40000000-0000-4000-8000-000000000008","prompt":"Es regnet stark. Wir fahren trotzdem mit dem Rad. ___ es stark regnet, fahren wir mit dem Rad.","instruction":{"en":"Choose the word that expresses the intended meaning.","de":"Wähle das Wort, das die gemeinte Bedeutung ausdrückt."},"hint":{"en":"Look at the relationship between the two ideas.","de":"Achte auf den Zusammenhang zwischen den beiden Aussagen."},"slots":[{"id":"form","label":"Verbindung","options":[{"id":"Obwohl","text":"Obwohl"},{"id":"Weil","text":"Weil"},{"id":"Wenn","text":"Wenn"},{"id":"Damit","text":"Damit"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"form","optionId":"Obwohl"}]}],"explanation":{"en":"Obwohl introduces a fact that contrasts with the expected outcome; the verb comes last.","de":"Obwohl drückt einen Gegensatz zur Erwartung aus. Das finite Verb steht am Ende."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Es regnet stark. Wir fahren trotzdem mit dem Rad. ","emphasis":false},{"text":"Obwohl","emphasis":true},{"text":" es stark regnet, fahren wir mit dem Rad.","emphasis":false}]}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
