INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001022','4','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001022","revision":4,"targetId":"40000000-0000-4000-8000-000000000011","prompt":"Ich besuche einen Kurs, um meine Aussprache ___ verbessern. (Infinitivpartikel)","instruction":{"en":"Choose the form that correctly completes the sentence.","de":"Wähle die Form, die den Satz richtig ergänzt."},"hint":{"en":"A purpose clause with um needs an infinitive marker immediately before the verb.","de":"In einem Finalsatz mit um steht unmittelbar vor dem Infinitiv eine Partikel."},"slots":[{"id":"form","label":"Form","options":[{"id":"zum","text":"zum"},{"id":"für","text":"für"},{"id":"zu","text":"zu"},{"id":"an","text":"an"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"form","optionId":"zu"}]}],"explanation":{"en":"Um … zu expresses purpose when both clauses have the same subject.","de":"Um … zu beschreibt eine Absicht, wenn beide Satzteile dasselbe Subjekt haben."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich besuche einen Kurs, um meine Aussprache ","emphasis":false},{"text":"zu","emphasis":true},{"text":" verbessern.","emphasis":false}]}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
