INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001024','4','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001024","revision":4,"targetId":"40000000-0000-4000-8000-000000000012","prompt":"Ich habe vor, mich auf das Gespräch ___. (vorbereiten, Infinitiv mit zu)","instruction":{"en":"Choose the form that correctly completes the sentence.","de":"Wähle die Form, die den Satz richtig ergänzt."},"hint":{"en":"Put zu between the prefix and the verb stem.","de":"Setze zu zwischen Vorsilbe und Verbstamm."},"slots":[{"id":"form","label":"Form","options":[{"id":"vorzubereiten","text":"vorzubereiten"},{"id":"vorbereiten","text":"vorbereiten"},{"id":"zubereiten","text":"zubereiten"},{"id":"vorzubereite","text":"vorzubereite"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"form","optionId":"vorzubereiten"}]}],"explanation":{"en":"With separable verbs, zu is inserted: vorbereiten → vorzubereiten; teilnehmen → teilzunehmen.","de":"Bei trennbaren Verben steht zu im Wort: vorbereiten → vorzubereiten; teilnehmen → teilzunehmen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich habe vor, mich auf das Gespräch ","emphasis":false},{"text":"vorzubereiten","emphasis":true},{"text":".","emphasis":false}]}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
