INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001026','4','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001026","revision":4,"targetId":"40000000-0000-4000-8000-000000000013","prompt":"Der Vertrag, ___ ich gestern unterschrieben habe, gilt ab Mai. (Relativpronomen)","instruction":{"en":"Choose the form that correctly completes the sentence.","de":"Wähle die Form, die den Satz richtig ergänzt."},"hint":{"en":"The relative pronoun is the object of the relative clause.","de":"Das Relativpronomen ist das Objekt im Relativsatz."},"slots":[{"id":"form","label":"Form","options":[{"id":"dem","text":"dem"},{"id":"der","text":"der"},{"id":"den","text":"den"},{"id":"das","text":"das"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"form","optionId":"den"}]}],"explanation":{"en":"For a masculine accusative antecedent use den; for a neuter one use das.","de":"Im Akkusativ steht bei einem maskulinen Bezugswort den, bei einem neutralen das."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Vertrag, ","emphasis":false},{"text":"den","emphasis":true},{"text":" ich gestern unterschrieben habe, gilt ab Mai.","emphasis":false}]}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
