INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001028','4','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001028","revision":4,"targetId":"40000000-0000-4000-8000-000000000014","prompt":"Die Kollegin, ___ ich geholfen habe, bedankt sich. (Relativpronomen)","instruction":{"en":"Choose the form that correctly completes the sentence.","de":"Wähle die Form, die den Satz richtig ergänzt."},"hint":{"en":"Helfen and mit require the dative.","de":"Helfen und mit verlangen den Dativ."},"slots":[{"id":"form","label":"Form","options":[{"id":"der","text":"der"},{"id":"die","text":"die"},{"id":"dem","text":"dem"},{"id":"den","text":"den"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"form","optionId":"der"}]}],"explanation":{"en":"The dative relative pronouns are dem for masculine/neuter and der for feminine.","de":"Im Dativ lauten die Relativpronomen dem bei maskulinen und neutralen, der bei femininen Bezugswörtern."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kollegin, ","emphasis":false},{"text":"der","emphasis":true},{"text":" ich geholfen habe, bedankt sich.","emphasis":false}]}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
